import {useCallback} from 'react'
import {RefSelector} from '@github-ui/ref-selector'
import type {Repository} from '../types/repository'

interface BranchPickerProps {
  repository: Repository
  branchListCacheKey: string
  selectedBranchName: string | null
  onSelect: (branchName: string) => void
}

export function BranchPicker({repository, branchListCacheKey, selectedBranchName, onSelect}: BranchPickerProps) {
  const handleSelect = useCallback(
    (ref: string) => {
      onSelect(ref)
    },
    [onSelect],
  )

  return (
    <RefSelector
      types={['branch']}
      buttonText={selectedBranchName || 'Select a branch'}
      ariaLabel={selectedBranchName ? `branch ${selectedBranchName}` : 'Select a branch'}
      actionListHeadingText="Select a branch"
      hideShowAll
      canCreate={false}
      currentCommitish={selectedBranchName ?? ''}
      owner={repository.ownerLogin}
      repo={repository.name}
      defaultBranch={repository.defaultBranch}
      cacheKey={branchListCacheKey}
      onSelectItem={handleSelect}
      selectedRefType="branch"
      closeOnSelect
    />
  )
}
